//SIU register.
//there's 2 set of timing DDR timing parameter for 2 set of DDR frequency parameter.
//when change frequency, the hardware would automatically select one of these two set of timing parameter
//DMC_DRAM_* is for Frequency set 0.
//DMC_NFQ_* is for Frequency set 1.
#define DMC_DRAM_TMRD                              ((0x0100  << 2) + 0xfe036000)
