  //bit 14:8.  DDR base address in 128Mbyte unit. 7 bits is enough for 16 GB DDR space.
  //bit 7:6.  for strip4 mode:  2'b00:  strip_position == 2'b00 for this dmc.
                              //2'b01:  strip_position == 2'b01 for this dmc.
                              //2'b10:  strip_position == 2'b10 for this dmc.
                              //2'b11:  strip_position == 2'b11 for this dmc.
             //for strip2 mode:
                             //2'b00  stip_position = 1'b0 for this dmc.
                             //2'b01  stip position = 1'b1 for this dmc.
  //bit 5. rank_sel.  1 : rank1.  0 : rank0.
  //bit 4  not used in P1.
  //bit 3  not used in P1.
  //bit 2  not used.
  //bti 1:0. map mode.  2'b00. this region is no mapped to this DMC channel.
                    //  2'b01. this region is all maped to this DMC channel.
                    //  2'b10. this region is mapped to 2 DMC in interleaving mode(strip2 mode ).
                    //  2'b11. this region is mapped to 4 DMC in interleaving mode(strip4 mode ).

#define DMC_AXI2DDR2                               ((0x0522  << 2) + 0xfe036000)
  //for AXI address 0x0_4000_0000 ~ 0x0_5fff_ffff
  //bit 31:22. not used.
  //bit 21:16. TAG cache address offset for this 512MByte data area. Unit : 8Mbyte
  //bit 14:8.  DDR base address in 128Mbyte unit. 7 bits is enough for 16 GB DDR space.
  //bit 7:6.  for strip4 mode:  2'b00:  strip_position == 2'b00 for this dmc.
                              //2'b01:  strip_position == 2'b01 for this dmc.
                              //2'b10:  strip_position == 2'b10 for this dmc.
                              //2'b11:  strip_position == 2'b11 for this dmc.
             //for strip2 mode:
                             //2'b00  stip_position = 1'b0 for this dmc.
                             //2'b01  stip position = 1'b1 for this dmc.
  //bit 5. rank_sel.  1 : rank1.  0 : rank0.
  //bit 4  not used in P1.
  //bit 3  not used in P1.
  //bit 2  not used.
  //bti 1:0. map mode.  2'b00. this region is no mapped to this DMC channel.
                    //  2'b01. this region is all maped to this DMC channel.
                    //  2'b10. this region is mapped to 2 DMC in interleaving mode(strip2 mode ).
